"""
XGO 机器人控制库
统一入口，自动选择设备类型
"""

# 直接导入所有类
from .xgolib_dog import XGO_DOG
from .xgolib_rider import XGO_RIDER


__version__ = '1.0.0'
__all__ = ['XGO', 'XGO_DOG', 'XGO_RIDER']

def XGO(version="auto",port="/dev/ttyAMA0", baud=115200,  verbose=False):
    """
    统一的XGO类工厂函数

    Args:
        port: 串口设备路径
        baud: 波特率
        version: 设备版本 
            "auto" - 自动检测
            "xgomini" - XGO-MINI
            "xgolite" - XGO-LITE  
            "xgomini3w" - XGO-MINI3W
            "xgorider" - XGO-RIDER
        verbose: 是否显示调试信息
    """
    if version == "auto":
        try:

            temp_dog: XGO_DOG = XGO_DOG(port, baud, version="xgomini", verbose=verbose)
            firmware: str = temp_dog.read_firmware()
            print(f"Detected firmware: {firmware}")

            if firmware and firmware[0] == 'R':
                print("Auto-detected: XGO-RIDER")
                return XGO_RIDER(port, baud, version="xgorider", verbose=verbose)
            elif firmware and firmware[0] in ['M', 'L', 'W']:
                print(f"Auto-detected: XGO-{firmware[0]}")
                return XGO_DOG(port, baud, version="auto", verbose=verbose)
            else:
                print("Auto-detection failed, using default: XGO-MINI")
                return XGO_DOG(port, baud, version="xgomini", verbose=verbose)

        except Exception as e:
            print(f"Auto detection failed: {e}, using default: XGO-MINI")
            return XGO_DOG(port, baud, version="xgomini", verbose=verbose)

    elif version in ["xgomini", "xgolite", "xgomini3w","mini", "lite", "mini3w"]:
        return XGO_DOG(port, baud, version=version, verbose=verbose)

    elif version == "xgorider" or version == "rider":
        return XGO_RIDER(port, baud, version=version, verbose=verbose)

    else:
        print(f"Warning: Unknown version '{version}', using 'xgomini' instead")
        return XGO_DOG(port, baud, version="xgomini", verbose=verbose)

#!/usr/bin/env python3
"""XGO AI语音识别"""
import sys
import os
sys.path.insert(0, os.path.join(os.path.dirname(__file__), '../../lib'))
import argparse
import uuid
import base64
import requests
from edulib import XGOEDU

def main():
    parser = argparse.ArgumentParser(description='XGO AI语音识别')
    parser.add_argument('--seconds', type=int, default=3, help='录音时长(秒)，默认3秒')
    parser.add_argument('--api-key', type=str, default=os.environ.get('DASHSCOPE_API_KEY'), help='阿里云API密钥（默认从环境变量DASHSCOPE_API_KEY读取）')
    args = parser.parse_args()

    if not args.api_key:
        print('错误: 未提供API密钥，请设置环境变量DASHSCOPE_API_KEY或使用--api-key参数')
        return

    edu = XGOEDU()

    temp_audio = f"/tmp/speech_{uuid.uuid4().hex}.wav"

    edu.lcd_clear()
    edu.lcd_text(5, 5, "录音中...", "YELLOW", 14)
    edu.lcd_text(5, 30, f"时长: {args.seconds}秒", "WHITE", 12)

    os.system(f"arecord -d {args.seconds} -f S16_LE -r 16000 -c 1 -t wav {temp_audio}")

    if not os.path.exists(temp_audio):
        print("录音文件不存在")
        return

    with open(temp_audio, "rb") as f:
        audio_data = base64.b64encode(f.read()).decode('utf-8')

    edu.lcd_text(5, 55, "识别中...", "CYAN", 12)

    headers = {
        "Authorization": "Bearer " + args.api_key,
        "Content-Type": "application/json"
    }

    data = {
        "model": "qwen3-omni-30b-a3b-captioner",
        "messages": [
            {"role": "user", "content": [
                {"type": "input_audio", "input_audio": {"data": "data:audio/wav;base64," + audio_data}}
            ]}
        ]
    }

    response = requests.post(
        "https://dashscope.aliyuncs.com/compatible-mode/v1/chat/completions",
        headers=headers, json=data, timeout=30
    )

    if os.path.exists(temp_audio):
        os.remove(temp_audio)

    if response.status_code == 200:
        result = response.json()
        if "choices" in result and len(result["choices"]) > 0:
            text = result["choices"][0]["message"]["content"]
            print(f"识别结果: {text}")
        else:
            print("API返回数据格式异常")
    else:
        print(f"API请求失败: {response.status_code}")

if __name__ == '__main__':
    main()

#!/usr/bin/env python3
"""读取XGO-Rider电池电量"""
import sys
import os
sys.path.insert(0, os.path.join(os.path.dirname(__file__), '../../lib'))
import argparse
from xgolib import XGO

def main():
    parser = argparse.ArgumentParser(description='读取XGO-Rider电池电量')
    args = parser.parse_args()

    dog = XGO()
    battery = dog.rider_read_battery()

    if battery >= 80:
        status = "电量充足"
    elif battery >= 50:
        status = "电量正常"
    elif battery >= 20:
        status = "电量偏低"
    else:
        status = "电量严重不足，请及时充电"

    print(f"Rider电池电量: {battery}% - {status}")

if __name__ == '__main__':
    main()

